//! Deterministic DSD upconversion: DSF, DFF, WAV or FLAC in, DSD128 or DSD256 out (and
//! DSD64 from PCM).
//!
//! Container I/O and the DSD64 decimator come from the `dsd2pcm` crate. This crate adds
//! the interpolators, the sigma-delta modulators and the conversion pipeline
//! ([`mod@convert`]). Every coefficient is a committed table (`tables.rs`, generated by
//! `tools/gen_tables.py`), arithmetic is scalar `f64` in a fixed order without fused
//! multiply-add, so the output bytes are the same on every platform and build profile.
#![forbid(unsafe_code)]
#![warn(missing_docs)]

pub mod convert;
mod filters;
pub mod id3;
pub mod modulator;
#[rustfmt::skip]
mod resample_table;
pub mod stream;
#[rustfmt::skip]
mod tables;
pub mod testsignal;

pub use convert::{
    accepted_orders, cancelled, convert, convert_file, convert_file_to, convert_file_with,
    convert_with, is_cancelled, Band, Container, FileOutput, InputFormat, Options, Output,
    Progress, Report, DEFAULT_GAIN_DB, DEFAULT_INPUT_LIMIT,
};
pub use dsd2pcm;
pub use dsd2pcm::{Error, Result};
pub use stream::Stream;

/// This library's version, `X.Y.Z` (the crate version): the same string as the C library's
/// `dsdup_version()`.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// The engine's identity at run time, `dsd-upsample/X.Y.Z`, for a consumer's cache keys and
/// logs.
///
/// Within a release, the output for the same input and [`Options`] is designed to be
/// byte-identical on every platform and with any number of threads (golden hashes in CI);
/// between releases it may change, and the changelog lists each such change. So a cache of
/// converted output keyed by this id (with the input and the options) stays valid until the
/// id changes.
pub fn engine_id() -> &'static str {
    concat!("dsd-upsample/", env!("CARGO_PKG_VERSION"))
}

#[cfg(test)]
mod version_tests {
    #[test]
    fn engine_id_names_the_crate_version() {
        assert_eq!(super::VERSION, env!("CARGO_PKG_VERSION"));
        assert_eq!(
            super::engine_id(),
            format!("dsd-upsample/{}", super::VERSION)
        );
        let parts: Vec<&str> = super::VERSION.split('.').collect();
        assert_eq!(parts.len(), 3, "{}", super::VERSION);
        assert!(
            parts.iter().all(|p| p.parse::<u32>().is_ok()),
            "{}",
            super::VERSION
        );
    }
}
#[cfg(test)]
mod stage_timings {
    //! Rough per-stage timings: `cargo test --release --lib stage_timings -- --ignored --nocapture`.
    #[test]
    #[ignore]
    fn stages() {
        use std::time::Instant;
        let n = 11_289_600usize;
        let u: Vec<f64> = (0..n)
            .map(|i| 0.25 * ((i % 1000) as f64 / 500.0 - 1.0))
            .collect();
        let mut m =
            crate::modulator::Modulator::new(crate::tables::modulator(256, 7, true).unwrap(), 0.6);
        let t = Instant::now();
        let mut c = 0u64;
        m.run(&u, &mut |b| c += u64::from(b));
        eprintln!("modulator 1 s DSD256: {:?} ({c})", t.elapsed());
        let mut chain: Vec<_> = [705_600u32, 1_411_200, 2_822_400, 5_644_800, 11_289_600]
            .iter()
            .map(|&r| {
                crate::filters::Interpolator::new(match r {
                    705_600 => &crate::tables::HB_705600,
                    1_411_200 => &crate::tables::HB_1411200,
                    2_822_400 => &crate::tables::HB_2822400,
                    5_644_800 => &crate::tables::HB_5644800,
                    _ => &crate::tables::HB_11289600,
                })
            })
            .collect();
        let x: Vec<f64> = u[..352_800].to_vec();
        let t = Instant::now();
        let mut a = x;
        for it in &mut chain {
            let mut b = Vec::new();
            it.process(&a, &mut b);
            a = b;
        }
        eprintln!("interp 1 s to DSD256: {:?} ({})", t.elapsed(), a.len());
        for blk in [256usize, 1024, 4096] {
            let t = Instant::now();
            let (mut a, mut b) = (Vec::new(), Vec::new());
            let mut total = 0;
            for x in u[..352_800].chunks(blk) {
                a.clear();
                a.extend_from_slice(x);
                for it in &mut chain {
                    b.clear();
                    it.process(&a, &mut b);
                    std::mem::swap(&mut a, &mut b);
                }
                total += a.len();
            }
            eprintln!("interp blocks of {blk}: {:?} ({total})", t.elapsed());
        }
        // the 48 kHz-family resampler: to the partner rate (down 160, the shipped plan) and
        // to twice it (down 80, the alternative that skips the steep x2 stage after it)
        let t = &crate::resample_table::RESAMPLE_147;
        for (fs, down) in [(48_000usize, 160usize), (48_000, 80), (384_000, 160)] {
            let x: Vec<f64> = u[..fs].to_vec();
            let mut r = crate::filters::Resampler::new(t, down);
            let mut o = Vec::new();
            let t0 = Instant::now();
            for blk in x.chunks(fs / 16) {
                r.process(blk, &mut o);
            }
            eprintln!(
                "resample 1 s of {fs} Hz, down {down}: {:?} ({})",
                t0.elapsed(),
                o.len()
            );
        }
        let mut it = crate::filters::Interpolator::new(&crate::tables::STEEP_44100);
        let x: Vec<f64> = u[..44_100].to_vec();
        let mut o = Vec::new();
        let t0 = Instant::now();
        for blk in x.chunks(2756) {
            it.process(blk, &mut o);
        }
        eprintln!("steep x2 1 s of 44.1 kHz: {:?} ({})", t0.elapsed(), o.len());
        let mut d = crate::filters::Decimator::new(&crate::tables::DECIM_DSD64);
        let bytes: Vec<u8> = (0..352_800).map(|i| (i * 37) as u8).collect();
        let t = Instant::now();
        let mut o = Vec::new();
        d.push(&bytes, &mut o);
        eprintln!("decim 1 s DSD64: {:?} ({})", t.elapsed(), o.len());
    }
}
